// Antwort des Cockpits mit dem gemeldeten Lauf zusammenführen — kurz und ohne Dokumentinhalte.
// Zusätzlich (02.11.2026, Punkt 3): aus den sicheren Kennwerten der Engine die Stammdaten-
// Kandidaten für das Mandat ableiten — Übersetzung nur über die Konfigurationstabellen.
const meldung = $('Lauf-Ende von Modul 01 (Header-Auth)').first().json.body ?? {};
const konfig = $('Cockpit (hier anpassen)').first().json ?? {};
const antwort = $input.first().json ?? {};

const tabelle = (v) => {
  let roh = v;
  if (typeof roh === 'string') { try { roh = JSON.parse(roh); } catch { roh = {}; } }
  const aus = {};
  for (const [k, w] of Object.entries(roh && typeof roh === 'object' ? roh : {})) {
    if (typeof w === 'string' && w.trim() !== '') aus[String(k).trim().toLowerCase()] = w.trim();
  }
  return aus;
};
const stadtBundesland = tabelle(konfig.stadtBundesland);
const nutzungAssetklasse = tabelle(konfig.nutzungAssetklasse);

const laufPraefix = (s) => String(s ?? '').replace(/_\d{8}-\d{6}$/, '').trim();
const istTestlauf = (s) => /^(test|demo)[-_ ]/i.test(s);
const kw = meldung.kennwerte && typeof meldung.kennwerte === 'object' ? meldung.kennwerte : {};
const mandatName = laufPraefix(meldung.objekt);

const kandidat = {};
if (typeof kw.ort === 'string' && kw.ort.trim() !== '') {
  const ort = kw.ort.trim();
  kandidat.stadt = ort;
  const schluessel = ort.toLowerCase();
  const bundesland = stadtBundesland[schluessel] ?? stadtBundesland[schluessel.split(/\s*[,(/]\s*/)[0]];
  if (bundesland) kandidat.region = bundesland;
}
if (typeof kw.nutzung === 'string' && nutzungAssetklasse[kw.nutzung.trim().toLowerCase()]) {
  kandidat.assetklasse = nutzungAssetklasse[kw.nutzung.trim().toLowerCase()];
}
const stammdatenPruefen =
  meldung.status === 'fertig' && mandatName !== '' && !istTestlauf(mandatName) && Object.keys(kandidat).length > 0;

return [{ json: {
  ok: antwort.ok === true,
  lauf: meldung.lauf ?? null,
  objekt: meldung.objekt ?? null,
  laufStatus: meldung.status ?? null,
  angelegt: Array.isArray(antwort.angelegt) ? antwort.angelegt : [],
  uebersprungen: Array.isArray(antwort.uebersprungen) ? antwort.uebersprungen : [],
  abgleiche: antwort.abgleiche ?? null,
  cockpitFehler: antwort.ok === true ? null : (antwort.grund ?? antwort.fehler ?? 'Cockpit hat nicht mit ok geantwortet'),
  cockpitBasis: konfig.cockpitBasis ?? null,
  mandatName,
  kennwerte: kw,
  stammdatenKandidat: kandidat,
  stammdatenPruefen,
  stammdaten: stammdatenPruefen ? null : { ok: true, geschrieben: {}, grund: istTestlauf(mandatName) ? 'Testlauf' : (meldung.status !== 'fertig' ? 'Lauf nicht fertig' : 'keine sicheren Kennwerte') },
} }];

// Nur Felder füllen, die im Mandat noch leer sind — Einträge von Menschen bleiben unangetastet.
const z = $('Ergebnis zusammenfassen').first().json;
const antwort = $input.first().json ?? {};
const mandate = Array.isArray(antwort.mandate) ? antwort.mandate : [];
const m = mandate.find((x) => x.name === z.mandatName || x.laufPraefix === z.mandatName);
const schreiben = {};
if (m) {
  for (const [feld, wert] of Object.entries(z.stammdatenKandidat ?? {})) {
    const ist = m[feld];
    if (ist === null || ist === undefined || String(ist).trim() === '') schreiben[feld] = wert;
  }
}
const anzahl = Object.keys(schreiben).length;
return [{ json: {
  ...z,
  mandatGefunden: m !== undefined,
  stammdatenSchreiben: schreiben,
  stammdatenAnzahl: anzahl,
  stammdatenBody: m ? JSON.stringify({ name: m.name, ...schreiben }) : null,
  stammdaten: anzahl > 0 ? null : { ok: true, geschrieben: {}, grund: m ? 'Felder bereits gefüllt' : 'Mandat nicht im Cockpit gefunden' },
} }];

// Ergebnis des Stammdaten-Schreibens an die Lauf-Zusammenfassung hängen.
const z = $('Nur leere Felder füllen').first().json;
const a = $input.first().json ?? {};
const { stammdatenBody, ...rest } = z;
return [{ json: {
  ...rest,
  stammdaten: {
    ok: a.ok === true,
    geschrieben: a.ok === true ? z.stammdatenSchreiben : {},
    abgleich: a.abgleich ?? null,
    fehler: a.ok === true ? null : (a.grund ?? a.fehler ?? 'Cockpit hat nicht mit ok geantwortet'),
  },
} }];
